55	const PROCESSING_FEE = 5;
56	
57	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
58	
59	const BASE_PREMIUMS = {
60	  sword: 100,
61	  amulet: 60,
62	  staff: 80,
63	  potion: 40,
64	  rune: 25,
65	  moonstone: 25,
66	} as const satisfies Record<string, number>;
67	
68	type InsurableItemType = keyof typeof BASE_PREMIUMS;
69	
70	const basePremiumForItems = (items: Item[]): number =>
71	  items.reduce(
72	    (sum, item) => sum + BASE_PREMIUMS[item.type as InsurableItemType],
73	    0,
74	  );
75	
76	const withInitialAssessmentSurcharge = (basePremium: number): number =>
77	  basePremium * (1 + INITIAL_ASSESSMENT_SURCHARGE);
78	
79	const quotePremium = (items: Item[]): number =>
80	  Math.round(
81	    withInitialAssessmentSurcharge(basePremiumForItems(items)) + PROCESSING_FEE,
82	  );
83	
84	const runStep = (step: Step): StepResult => {
85	  if (step.op === "quote") return { premium: quotePremium(step.items) };
86	  throw new Error(`Unsupported step: ${step.op}`);
87	};
88	
89	export const runScenario = (scenario: Scenario): ScenarioResult => ({
90	  results: scenario.steps.map(runStep),
91	});
