const isInsurableItemType = (type: string): type is InsurableItemType =>
  type in BASE_PREMIUMS;

const basePremiumForItem = (item: Item): number => {
  if (!isInsurableItemType(item.type)) return 0;
  return BASE_PREMIUMS[item.type];
};

const basePremiumForItems = (items: Item[]): number =>
  items.reduce((sum, item) => sum + basePremiumForItem(item), 0);
